import{_ as s,o as e,c as a,aO as l}from"./chunks/framework.BFrk9dwu.js";const o="/recipes/braised-chicken.jpg",r="/recipes/braised-chicken/top-2.jpg",d="/recipes/braised-chicken/top-3.jpg",i="/recipes/braised-chicken/step-1-a.jpg",c="/recipes/braised-chicken/step-2-a.jpg",n="/recipes/braised-chicken/step-3-a.jpg",p="/recipes/braised-chicken/step-4-a.jpg",g="/recipes/braised-chicken/step-6-a.jpg",h="/recipes/braised-chicken/step-6-b.jpg",x=JSON.parse('{"title":"红烧鸡","description":"鸡块焯水、煸出油、炒糖色、小火焖透的红烧鸡做法，含上色发黑、肉柴、收汁糊底的排查","frontmatter":{"date":"2026-11-15T13:51:13.000Z","title":"红烧鸡","description":"鸡块焯水、煸出油、炒糖色、小火焖透的红烧鸡做法，含上色发黑、肉柴、收汁糊底的排查","permalink":"/pages/27f597","categories":["life","recipes"]},"headers":[],"relativePath":"life/recipes/braised-chicken.md","filePath":"life/recipes/braised-chicken.md","lastUpdated":1794727195000}'),m={name:"life/recipes/braised-chicken.md"};function u(_,t,b,f,k,y){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="红烧鸡" tabindex="-1">红烧鸡 <a class="header-anchor" href="#红烧鸡" aria-label="Permalink to &quot;红烧鸡&quot;">​</a></h1><p><strong>分类：家常小炒</strong></p><div class="recipe-gallery"><img src="'+o+'" alt="红烧鸡成品：白瓷盘里枣红色的鸡块挂着浓汁，撒了葱段"><img src="'+r+'" alt="俯拍特写：剁块的鸡块裹着浓汁，盘边八角与桂皮"><img src="'+d+'" alt="盛在小碗里，筷子夹起一块鸡块，旁边一碗白米饭"><img src="'+i+'" alt="原料摆拍：生鸡块、冰糖、姜片八角桂皮干辣椒、泡发香菇"></div><p>红烧鸡没什么玄学，就三步：焯水去腥、煸到出油、上色后小火焖。糖色和收汁这两下决定卖相，火候别急，急了两样都毁。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>鸡</td><td>剁 4cm 左右的块，土鸡更香但要焖 35 分钟以上</td></tr><tr><td>冰糖</td><td>炒糖色用，没有就用等量白糖</td></tr><tr><td>生姜</td><td>5 片，3 片焯水，2 片煸炒</td></tr></tbody></table><p><strong>调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>食用油</td><td>煸鸡块用</td></tr><tr><td>料酒</td><td>焯水、煸炒</td></tr><tr><td>生抽</td><td>调味主力</td></tr><tr><td>老抽</td><td>只管上色，多了发黑</td></tr><tr><td>八角</td><td>拍裂更出味</td></tr><tr><td>桂皮</td><td>1 小段</td></tr><tr><td>干辣椒</td><td>不吃辣可以不放</td></tr><tr><td>热水</td><td>必须热水，冷水一激肉就柴</td></tr><tr><td>盐</td><td>收汁前尝过再决定补不补</td></tr><tr><td>小葱</td><td>最后撒</td></tr><tr><td>配菜</td><td>根据自己的喜好，比如：豆角、土豆、香菇</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>泡水。</strong> 鸡块冷水泡 20 分钟把血水泡出来，中途换一次水。块别剁太小，4cm 左右，焖完还会缩一圈。</p><figure class="recipe-shots"><img loading="lazy" src="'+i+'" alt="鸡块泡在冷水里，水面带出血色"></figure></li><li><p><strong>焯水。</strong> 鸡块冷水下锅，加姜、料酒，水开后撇干净浮沫，再煮 2 分钟捞出。<strong>冲洗用温水</strong>，冷水冲会让肉纤维骤缩，后面焖多久都回不来。</p><figure class="recipe-shots"><img loading="lazy" src="'+c+'" alt="鸡块冷水下锅，水面浮起灰白色浮沫"></figure></li><li><p><strong>煸出油。</strong> 锅烧热下油，鸡块皮朝下摊平，中火煸，把鸡皮里的油逼出来，表面微黄再翻面。</p><ul><li><p>这层鸡油是炒糖色的底，也是香味的来源。偷懒直接加水，成品就是「水煮鸡」的味道。</p></li><li><p>下香料。 加姜、八角、桂皮、干辣椒炒香</p></li></ul><figure class="recipe-shots"><img loading="lazy" src="'+n+'" alt="鸡块皮朝下在锅里煎到金黄"></figure></li><li><p><strong>炒糖色。</strong> 转小火，鸡块推到锅边，空出来的油里下 20g 冰糖，慢慢炒到化开、变成枣红色起小泡，立刻把鸡块翻进去裹匀。<strong>看到枣红就动手</strong>，多炒十秒就发苦。</p><ul><li>不会炒糖色的，沿锅边淋料酒，再加生抽、老抽翻匀上色。</li></ul><figure class="recipe-shots"><img loading="lazy" src="'+p+'" alt="冰糖在油里化成枣红色、起小泡"></figure></li><li><p><strong>热水焖。</strong> 倒热水没过鸡块，放配料，大火烧开转小火，盖盖焖。土鸡、老母鸡要焖久一点。</p><figure class="recipe-shots"><img loading="lazy" src="'+g+'" alt="热水没过鸡块，配料一起下锅"><img loading="lazy" src="'+h+'" alt="盖盖转小火，锅盖缝冒白汽"></figure></li><li><p><strong>大火收汁。</strong> 转大火收汁，收到汤汁能挂住勺背就关火，撒葱花。<strong>别收到发干</strong>，凉了还会更稠。</p><figure class="recipe-shots"><img src="'+r+'" alt="俯拍特写：剁块的鸡块裹着浓汁，盘边八角与桂皮"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>冷水下锅焯、温水冲洗</strong>：冷水下锅血水才出得来，温水冲不会让肉骤缩。</li><li><strong>鸡皮朝下煸</strong>：煸出的鸡油是炒糖色的底，也是整锅香气的来源。</li><li><strong>糖色枣红就下鸡</strong>：颜色再深就是苦味，救不回来。</li><li><strong>全程热水</strong>：冷水一激，肉立刻变柴，后面焖多久都没用。</li><li><strong>收汁到挂勺</strong>：汤汁能挂在勺背上就关火，锅里看着正好，凉了会偏干。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">偷懒版</p><p>不会炒糖色就跳过第 4 步，用老抽上色，颜色浅一点但不会翻车。也可以买现成的红烧酱油，生抽老抽一并省掉，只补盐。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>颜色发黑发苦</strong>：糖色炒过了，或者老抽倒多了。</li><li><strong>鸡肉又柴又腥</strong>：没焯水、中途加了冷水，或者大火把汤烧干又补水。</li><li><strong>汤寡不挂味</strong>：鸡块没煸出油就加水，香味压根没出来。</li><li><strong>皮烂肉散</strong>：焖太久，或者全程大火滚。</li><li><strong>收汁糊底</strong>：糖分高，最后几分钟要不停推锅，别放着不管。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',16)])])}const q=s(m,[["render",u]]);export{x as __pageData,q as default};
